TYPE.TEST:


SetFunctionName("explicit VecFloat(VectorIntrinsicInParam v)");

MakeVectorIntrinsic(vr, 1.0f, 1.0f, 1.0f, 1.0f);
VecFloat vf0(vr);
union { unsigned int u; float f; } pun;
pun.u = 0x7fffffff;
float nan = pun.f;
MakeVectorIntrinsic(vr_nan, nan, nan, nan, nan);
// Create a VecFloat using NaN's, but don't bother doing any comparisons.
// (i.e. just make sure it is possible to do without asserting at runtime.)
VecFloat vfNaN(vr_nan);
(void)vfNaN; // Avoid compiler warning.

Validate( GetFloat(vf0) == 1.0f && GetFloat(vf0) == 1.0f && GetFloat(vf0) == 1.0f && GetFloat(vf0) == 1.0f );



SetFunctionName("VecFloat(VectorIntrinsicInParam v, int index)");

MakeVectorIntrinsic(vr, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloat vf0(vr, 0);
VecFloat vf1(vr, 1);
VecFloat vf2(vr, 2);
VecFloat vf3(vr, 3);

Validate(GetFloat(vf0) == 1.0f && GetFloat(vf1) == 2.0f && GetFloat(vf2) == 3.0f && GetFloat(vf3) == 4.0f);



SetFunctionName("VecFloat(float f)");

VecFloat vf0(1.0f);
VecFloat vf1(2.0f);

Validate(GetFloat(vf0) == 1.0f && GetFloat(vf1) == 2.0f);



SetFunctionName("passing int to VecFloat(float)");

//pass an int so we can validate implicit conversion to float
VecFloat vf1(1);

Validate(
    float_test_type(GetFloat(vf1)) == float_test_type(1.0)
    );



SetFunctionName("VecFloat(VecFloatRef<INDEX> v)");

MakeVectorIntrinsic(vr, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRefX vecFloatRefX(vr);
VecFloatRefY vecFloatRefY(vr);
VecFloatRefZ vecFloatRefZ(vr);
VecFloatRefW vecFloatRefW(vr);

VecFloat vf0(vecFloatRefX);
VecFloat vf1(vecFloatRefY);
VecFloat vf2(vecFloatRefZ);
VecFloat vf3(vecFloatRefW);

Validate(GetFloat(vf0) == 1.0f && GetFloat(vf1) == 2.0f && GetFloat(vf2) == 3.0f && GetFloat(vf3) == 4.0f);



SetFunctionName("VecFloat(VecFloatRefINDEX v)");

MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRefIndex refX(vi, 0);
VecFloatRefIndex refY(vi, 1);
VecFloatRefIndex refZ(vi, 2);
VecFloatRefIndex refW(vi, 3);

VecFloat vf0(refX);
VecFloat vf1(refY);
VecFloat vf2(refZ);
VecFloat vf3(refW);

Validate(GetFloat(vf0) == 1.0f && GetFloat(vf1) == 2.0f && GetFloat(vf2) == 3.0f && GetFloat(vf3) == 4.0f);



SetFunctionName("VecFloat(const VecFloat& v)");

VecFloat vf0(1.0f);
VecFloat vf1(2.0f);
VecFloat vf2(3.0f);
VecFloat vf3(4.0f);

VecFloat cvf0(vf0);
VecFloat cvf1(vf1);
VecFloat cvf2(vf2);
VecFloat cvf3(vf3);

Validate(vf0 == cvf0 && vf1 == cvf1 && vf2 == cvf2 && vf3 == cvf3);



SetFunctionName("float GetFloat() const");

VecFloat v(3.14f);
float f = GetFloat(v);
Validate(f == 3.14f);



SetFunctionName("VecFloat::WriteToFloat(float* f) const");

VecFloat v(1234.0f);
float f = 0.0f;
v.WriteToFloat(&f);
Validate(f == 1234.0f);



SetFunctionName("void SetFloat(float f)");

VecFloat v;
v.SetFloat(3.14f);
Validate(GetFloat(v) == 3.14f);



SetFunctionName("const VectorIntrinsic& GetVector() const");

VecFloat v(2.9f);
const VectorIntrinsic &vec = v.GetVector();
MakeVectorIntrinsic(ref, 2.9f, 2.9f, 2.9f, 2.9f);
Validate(memcmp(&ref,&vec,sizeof(ref))==0);



SetFunctionName("operator float() const");

VecFloat v(2.0f);
float f = v;
Validate(f == 2.0f);



SetFunctionName("operator float() const");

VecFloat v(0.0f);
v = 20.0f;
Validate(GetFloat(v) == 20.0f);



SetFunctionName("VecFloat& operator =(const VecFloat& f)");

VecFloat v1(2.0f);
VecFloat v2;
v2 = v1;
Validate(GetFloat(v2) == 2.0f);



SetFunctionName("VecFloat& operator =(const float& f)");

VecFloat v;
float f = 2.3f;
v = f;
Validate(GetFloat(v) == 2.3f);



SetFunctionName("VecFloat& operator =(const VecFloatRef<INDEX>& v)");

MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRef<VectorAxisZ> vr(vi);
VecFloat v;
v = vr;
Validate(GetFloat(v) == 3.0f);



SetFunctionName("VecFloat& operator =(const VecFloatRefIndex& v)");

MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRefIndex vr(vi, 3);
VecFloat v;
v = vr;
Validate(GetFloat(v) == 4.0f);



SetFunctionName("VecFloat Negate(VecFloat::InParam a) ; VecFloat operator - (VecFloat::InParam a)");

const float a = -7.0f;
VecFloat factoryA(7.0f);
VecFloat aVecFloat = Negate(factoryA);
Validate( IsEqualWithEpsilon(float_test_type(aVecFloat), float_test_type(a)) );



SetFunctionName("VecFloat Negate(VecFloatRef<INDEX> a) ; VecFloat operator - (VecFloatRef<INDEX> a)");

const float a = -1.0f;
MakeVectorIntrinsic(vr, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRefX vecFloatRefX(vr);
VecFloat aVecFloat = Negate(vecFloatRefX);
Validate( IsEqualWithEpsilon(float_test_type(aVecFloat), float_test_type(a)) );



SetFunctionName("VecFloat Negate(VecFloatRefIndex::InParam a) ; VecFloat operator - (VecFloatRefIndex::InParam a)");

const float a = -4.0f;
MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.0f, 4.0f);
VecFloatRefIndex vr(vi, 3);
VecFloat aVecFloat = Negate(vr);
Validate( IsEqualWithEpsilon(float_test_type(aVecFloat), float_test_type(a)) );



